def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    prev_bids = []
    strong_prev = 0.0
    cindy_prev = None
    david_prev = None
    for oid, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            prev_bids.append(bid)
            if bid > strong_prev:
                strong_prev = bid
        if oid == 'Cindy' and bid is not None:
            cindy_prev = float(bid)
        if oid == 'David' and bid is not None:
            david_prev = float(bid)

    urgent = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if not alive:
        return float(min(budget, 15.0))

    if slots >= 2:
        base = 18.0
        if cindy_prev is not None and cindy_prev >= 120:
            base = 12.0
        if david_prev is not None and david_prev < 60:
            base = 22.0
        if pressured:
            base = max(base, 48.0)
        if urgent:
            base = max(base, 78.0)
        return float(min(budget, base))

    target = 42.0
    if strong_prev > 0:
        target = max(target, strong_prev + 2.0)

    if cindy_prev is not None and cindy_prev >= 140:
        target = min(target, 96.0)
    if david_prev is not None and david_prev <= 70:
        target = max(target, david_prev + 3.0)

    if pressured:
        target = max(target, 72.0)
    if urgent:
        target = max(target, 95.0)

    if day >= 8 and hp >= 5 and no_water == 0:
        target = min(target, 65.0)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        # If no one is alive, take as much as needed but don't overspend.
        target = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, float(target))

    # Read yesterday bids from previous_trace for immediate reaction.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are likely needed today.
    # If supply is near max, competition likely drives bids up.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Pressure signal: if someone bid very high yesterday, they likely keep bidding.
    high_pressure = highest_prev_bid >= (DAILY_SALARY * 0.85)

    # Baseline bid: moderate, scaled by supply.
    # Keep it below typical aggressive bids unless my hp is healthy and supply is high.
    if high_pressure:
        # Try to stay in the game without matching extreme bids.
        if hp <= 2 or no_water_days >= 2:
            # Can't afford a loss; bid closer to aggressive range.
            desired = DAILY_SALARY * (0.75 + 0.1 * supply_ratio)
        else:
            desired = DAILY_SALARY * (0.55 + 0.25 * supply_ratio)
    else:
        # Lower competition: bid enough to secure water.
        if hp <= 2 or no_water_days >= 2:
            desired = DAILY_SALARY * (0.65 + 0.2 * supply_ratio)
        else:
            desired = DAILY_SALARY * (0.45 + 0.25 * supply_ratio)

    # Convert desired to a budget-safe bid.
    # Also cap by a fraction of budget to avoid going to 0 too early.
    budget_cap = budget
    if budget_cap < 0.0:
        budget_cap = 0.0

    # If budget is tight, scale down.
    if budget_cap <= DAILY_SALARY * 0.6:
        desired = min(desired, budget_cap * 0.9)
    else:
        desired = min(desired, budget_cap * 0.6)

    # If supply is low, competition is less intense; reduce bid.
    if supply_ratio < 0.35:
        desired *= 0.85

    # Ensure non-negative and not exceeding budget.
    bid = float(desired)
    if bid < 0.0:
        bid = 0.0
    if bid > budget_cap:
        bid = budget_cap

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_day = day_context['day']

    alive_opponents = [o for o_id, o in opponents_status.items() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.3)

    base_bid = DAILY_SALARY * 0.7

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.99
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.9
    elif my_no_water_days >= 1:
        base_bid = DAILY_SALARY * 0.85

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            if my_hp <= 3:
                base_bid = max(base_bid, highest_prev_bid + 2.5)
            else:
                base_bid = max(base_bid, highest_prev_bid * 1.01)
        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            base_bid = max(base_bid, highest_prev_bid + 1.5)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1)

    days_left = EPISODE_DAYS - current_day
    if days_left <= 2:
        if my_hp > 0:
            base_bid = max(base_bid, DAILY_SALARY * 1.0)
            if my_hp <= 1:
                base_bid = max(base_bid, my_budget)
    elif days_left <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)

    final_bid = min(my_budget, base_bid)

    if final_bid <= 0 and my_budget > 0:
        final_bid = 1.0

    final_bid = max(0.0, final_bid)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
